<?php
declare(strict_types=1);
final class PublicContactController{public function __construct(private PDO$db){}public function submit():string{if(!Env::bool('CONTACT_FORM_ENABLED',true))return view('website/pages/contact',['error'=>'El formulario no está disponible temporalmente.']);if(!verify_csrf())return view('website/pages/contact',['error'=>'La sesión del formulario expiró.']);if(!empty($_POST['website']))return redirect('contacto');$name=trim((string)($_POST['name']??''));$contact=trim((string)($_POST['email']??$_POST['phone']??''));$message=trim((string)($_POST['message']??''));if($name===''||$contact===''||$message===''||mb_strlen($message)>Env::int('CONTACT_FORM_MAX_MESSAGE_LENGTH',2000))return view('website/pages/contact',['error'=>'Completa los campos requeridos.']);$s=$this->db->prepare('INSERT INTO contact_messages(name,email,phone,subject,message,status,is_read) VALUES(?,?,?,?,?,?,0)');$s->execute([$name,filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)?$_POST['email']:null,trim((string)($_POST['phone']??'')),trim((string)($_POST['subject']??''))?:null,$message,'nuevo']);flash('success','Gracias. Recibimos tu mensaje y te responderemos pronto.');redirect('contacto');}}
